import{_ as a,C as r,o as n,c as i,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"Evidence: read effects and acceptance order","description":"","frontmatter":{"title":"Evidence: read effects and acceptance order","outline":"deep"},"headers":[],"relativePath":"en/research/evidence/2026-09-05-read-effects-acceptance-order.md","filePath":"en/research/evidence/2026-09-05-read-effects-acceptance-order.md","lastUpdated":1788665923000}'),d={name:"en/research/evidence/2026-09-05-read-effects-acceptance-order.md"};function l(c,e,h,p,u,f){const t=r("ArticleTableScroll");return n(),i("div",null,[o(t,{language:"en"}),e[0]||(e[0]=s('<h1 id="companion-evidence-read-effects-and-acceptance-order" tabindex="-1">Companion evidence: read effects and acceptance order <a class="header-anchor" href="#companion-evidence-read-effects-and-acceptance-order" aria-label="Permalink to &quot;Companion evidence: read effects and acceptance order&quot;">​</a></h1><p>Status: authorized by the user for bilingual publication on September 6, 2026. This is research evidence, not product safety acceptance or independent QA.</p><h2 id="claim-mapping" tabindex="-1">Claim mapping <a class="header-anchor" href="#claim-mapping" aria-label="Permalink to &quot;Claim mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim</th><th>Record set</th><th>Scope</th></tr></thead><tbody><tr><td>GET changes fixture business state; redirects change the request chain</td><td>observations.json / http / H0–H3</td><td>Deliberately constructed loopback service, not a third-party incident</td></tr><tr><td>Separate processes exchange a synthetic marker through a shared service</td><td>H4, H5</td><td>Channel existence, not autonomous collusion or tenant access control</td></tr><tr><td>Native gate allows shell GET but requires approval for POST</td><td>G1, G2, G6</td><td>Fixed function followed by real loopback curl, not a full Host session</td></tr><tr><td>Role capabilities reject unregistered tools and absent capabilities</td><td>G3–G5</td><td>Inner-policy ALLOW alone does not establish reachability</td></tr><tr><td>Replay order changes the transparent reducer&#39;s result</td><td>observations.json / order / O0–O6</td><td>Two rounds of forced ordering and fresh-process disk reads, not race frequency</td></tr><tr><td>Formal commands and roles already have relevant checks</td><td>baseline-1.log, baseline-2.log</td><td>31 unit/contract tests per round, not release acceptance</td></tr></tbody></table><h2 id="reading-the-ordering-experiment" tabindex="-1">Reading the ordering experiment <a class="header-anchor" href="#reading-the-ordering-experiment" aria-label="Permalink to &quot;Reading the ordering experiment&quot;">​</a></h2><ul><li>O0–O6 use equally authoritative inputs within one experimental scope, not a real business authorization service or a cross-user privilege hierarchy.</li><li>The Chinese article translates output <code>allow / deny / unknown</code> as 允许 / 禁止 / 未知 and input <code>revoke</code> as 撤销. Observation values are unchanged.</li><li>Both readers filter unaccepted input in O4. Unknown in O5/O6 follows our invalid-sequence rule, not Codex&#39;s legacy compatibility behavior.</li><li>The cutoff uses acceptance sequence; it does not validate all timestamp, visibility, or access-control boundaries in a real system.</li><li>The bilingual editorial revision on September 6, 2026 adds no experiments and changes no raw observations. The 14 ordering observations and 31 existing tests per round remain tied to the September 5 baseline.</li></ul><h2 id="check-and-rerun-commands" tabindex="-1">Check and rerun commands <a class="header-anchor" href="#check-and-rerun-commands" aria-label="Permalink to &quot;Check and rerun commands&quot;">​</a></h2><p><code>node check.mjs</code> checks exported observations, controls, repeatability, and the file manifest. It does not rerun product code or certify safety.</p><p><code>node probe-order.mjs</code> independently reruns the ordering fixture with Node, writing local fixtures/runs. It invokes neither a model nor a real business authorization service.</p><p><code>probe-http.mjs</code> is the actual probe with its hardcoded product root replaced by the <code>CODEFLOWMU_SOURCE_ROOT</code> environment variable. Running it requires authorized access to the fixed CodeFlowMu source, its existing tsx loader, and Windows curl.exe. This package does not duplicate product source. Invoke Node with <code>--import</code> pointing to that environment&#39;s tsx loader. The server binds only to 127.0.0.1 and mutates only synthetic fixture state.</p><p>Without the product source, readers can check exported observations and rerun the standalone ordering experiment, but cannot claim to have rerun the Native gate.</p><h2 id="version-de-identification-and-revisions" tabindex="-1">Version, de-identification, and revisions <a class="header-anchor" href="#version-de-identification-and-revisions" aria-label="Permalink to &quot;Version, de-identification, and revisions&quot;">​</a></h2><ul><li>Fixed commit: <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>; file hashes appear in observations.json.</li><li>Both rounds of all 13 HTTP/gate scenarios and seven ordering scenarios are retained. Forty observations are not an accuracy score.</li><li>Temporary paths, ports, PIDs, and full context objects are removed. Distinct-process evidence is retained as a boolean. Raw JSON hashes map provenance but do not reconstruct unpublished inputs.</li><li>The first HTTP launch failed on Windows ESM import syntax before any experiment ran; a file URL corrected the launcher.</li><li>An early G6 wrote G1&#39;s existing value. The final probe uses a separate namespace and distinguishes handler execution from value changes. Article tables use only the final two rounds.</li><li>Early ordering output did not distinguish received and accepted fields. The selected export does and includes cutoff checks.</li><li>Codex retains recording-order legacy compatibility. Our unknown result for missing/duplicate sequences is a control, not a copy of that behavior.</li></ul><p>No real Host restart, production incident dataset, independent QA, product fix, or development authorization is claimed.</p><h2 id="download-and-language" tabindex="-1">Download and language <a class="header-anchor" href="#download-and-language" aria-label="Permalink to &quot;Download and language&quot;">​</a></h2><p><a href="/joinwell52/zh/research/evidence/2026-09-05-read-effects-acceptance-order">中文</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/read-effects-order-evidence.zip" target="_blank" rel="noreferrer">Complete evidence ZIP</a>. Extract, enter the evidence directory, and run <code>node check.mjs</code>. Keep the complete directory; the script alone is insufficient.</p><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/baseline-1.log" target="_blank" rel="noreferrer">baseline-1.log</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/baseline-2.log" target="_blank" rel="noreferrer">baseline-2.log</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/check.mjs" target="_blank" rel="noreferrer">check.mjs</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/observations.json" target="_blank" rel="noreferrer">observations.json</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/probe-http.mjs" target="_blank" rel="noreferrer">probe-http.mjs</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/probe-order.mjs" target="_blank" rel="noreferrer">probe-order.mjs</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/README.en.md" target="_blank" rel="noreferrer">README.en.md</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/README.zh.md" target="_blank" rel="noreferrer">README.zh.md</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/evidence/sources.json" target="_blank" rel="noreferrer">sources.json</a></li></ul>',17))])}const g=a(d,[["render",l]]);export{m as __pageData,g as default};
